import{c as l,$ as e,Q as o,j as n,g as a,o as r,n as d,m as i}from"./chunks/framework.Ce_49mA8.js";const c="/img/ru/front/personal_dashboard.webp",y=JSON.parse('{"title":"Сводка капитала","description":"Практическое руководство по консолидированной инфопанели благосостояния, структуре абсолютного капитала и расчету бытовых трат по дельте в ОмниКрафт ЕРП.","frontmatter":{"title":"Сводка капитала","description":"Практическое руководство по консолидированной инфопанели благосостояния, структуре абсолютного капитала и расчету бытовых трат по дельте в ОмниКрафт ЕРП.","datePublished":"2026-10-28","dateModified":"2026-11-16","order":19},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/dashboard.md","filePath":"ru/docs/spaces/moy-kapital/dashboard.md","lastUpdated":1794787200000}'),p={name:"ru/docs/spaces/moy-kapital/dashboard.md"},g={id:"сводка-капитала-главная-инфопанель-благосостояния",tabindex:"-1"};function h(m,t,f,u,b,v){const s=e("DocIcon");return o(),n("div",null,[a("h1",g,[r(s,{name:"capital"}),t[0]||(t[0]=d(" Сводка капитала: Главная инфопанель благосостояния ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#сводка-капитала-главная-инфопанель-благосостояния","aria-label":'Permalink to "Сводка капитала: Главная инфопанель благосостояния"'},"​",-1))]),t[2]||(t[2]=i('<p>Вкладка <strong>«Сводка капитала»</strong> выступает главным командным пунктом мастера в пространстве «Мой капитал». Она выполняет сквозную консолидацию данных из изолированных баз данных всех производственных цехов, сервисных мастерских и личных счетов, формируя кристально ясный управленческий ответ на ключевой вопрос предпринимателя: <strong>какова реальная стоимость всего Вашего дела и личных активов прямо сейчас</strong>.</p><p>Инфопанель объединяет разрозненные финансовые потоки в единую систему координат, устраняя психологические ловушки учета: ощущение ложной бедности при масштабных инвестициях в материалы и станки либо иллюзию богатства при временном накоплении клиентских авансов на расчетной карте.</p><div class="craft-window-frame"><img src="'+c+'" alt="Сводка капитала в ОмниКрафт ЕРП" class="doc-image zoomable-img"></div><hr><h2 id="архитектура-абсолютного-капитала-четыре-базовых-столпа" tabindex="-1">Архитектура абсолютного капитала: четыре базовых столпа <a class="header-anchor" href="#архитектура-абсолютного-капитала-четыре-базовых-столпа" aria-label="Permalink to &quot;Архитектура абсолютного капитала: четыре базовых столпа&quot;">​</a></h2><p>Совокупное благосостояние мастера в ОмниКрафт ЕРП опирается на четыре фундаментальных контура. Каждый из них решает собственную задачу в управлении ресурсами:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Счета и кошельки (Деньги):</strong><br> Ликвидные остатки банковских карт, расчётных счетов, депозитов и наличных сейфов. </div></li><li><span class="craft-list-bullet"></span><div><strong>Инвестиционный портфель:</strong><br> Рыночная оценка ценных бумаг, фондов, криптовалютных активов, займов и долей в бизнесе. </div></li><li><span class="craft-list-bullet"></span><div><strong>Личные активы:</strong><br> Долгосрочное материальное имущество (недвижимость, автомобили, семейные ценности). </div></li><li><span class="craft-list-bullet"></span><div><strong>Имущество рабочих пространств:</strong><br> Чистые коммерческие активы действующих мастерских, студий и сервисных центров. </div></li></ul><h3 id="_1-счета-и-кошельки-ликвидныи-резерв" tabindex="-1">1. Счета и кошельки (Ликвидный резерв) <a class="header-anchor" href="#_1-счета-и-кошельки-ликвидныи-резерв" aria-label="Permalink to &quot;1. Счета и кошельки (Ликвидный резерв)&quot;">​</a></h3><p>Включает доступные свободные деньги на банковских картах, расчетных счетах, накопительных депозитах и в наличных сейфах. Если счета открыты в иностранных денежных единицах или расчетных цифровых активах, программа автоматически пересчитывает их в базовую валюту учета по актуальному курсу.</p><h3 id="_2-инвестиционныи-портфель-капитал-роста" tabindex="-1">2. Инвестиционный портфель (Капитал роста) <a class="header-anchor" href="#_2-инвестиционныи-портфель-капитал-роста" aria-label="Permalink to &quot;2. Инвестиционный портфель (Капитал роста)&quot;">​</a></h3><p>Отражает совокупную текущую рыночную стоимость внешних финансовых инструментов: акций, облигаций, паевых фондов, цифровых резервов, партнерских долей в сторонних предприятиях и выданных процентных займов.</p><h3 id="_3-личные-активы-материальныи-фундамент" tabindex="-1">3. Личные активы (Материальный фундамент) <a class="header-anchor" href="#_3-личные-активы-материальныи-фундамент" aria-label="Permalink to &quot;3. Личные активы (Материальный фундамент)&quot;">​</a></h3><p>Включает материальное имущество мастера вне бизнеса: жилую недвижимость, земельные участки, семейные автомобили и коллекционные ценности. Оценка учитывает персональную долю владения владельца, исключая надувание баланса чужими долями при совместной собственности.</p><h3 id="_4-имущество-рабочих-пространств-производственныи-капитал" tabindex="-1">4. Имущество рабочих пространств (Производственный капитал) <a class="header-anchor" href="#_4-имущество-рабочих-пространств-производственныи-капитал" aria-label="Permalink to &quot;4. Имущество рабочих пространств (Производственный капитал)&quot;">​</a></h3><p>Суммирует реальную балансовую стоимость всех зарегистрированных цехов и студий:</p><ul><li><strong>Касса рабочего пространства:</strong> фактический остаток денег по журналу ДДС цеха;</li><li><strong>Склад материалов и сырья:</strong> совокупная стоимость остатков кожи, дерева, металла и расходников, рассчитанная по <strong>скользящей средней стоимости (МАК)</strong>;</li><li><strong>Склад готовой продукции и верстак:</strong> себестоимость выпущенных изделий по <strong>методу первых партий (ФИФО)</strong> плюс прямые затраты в незавершенных партиях;</li><li><strong>Оборудование и станки:</strong> остаточная балансовая стоимость машин и инструмента цеха с учетом начисленной линейной амортизации и установленных долей использования.</li></ul><hr><h2 id="формула-расчета-абсолютного-капитала" tabindex="-1">Формула расчета абсолютного капитала <a class="header-anchor" href="#формула-расчета-абсолютного-капитала" aria-label="Permalink to &quot;Формула расчета абсолютного капитала&quot;">​</a></h2><p>В верхней части экрана расположена центральная карточка <strong>«Абсолютный капитал»</strong>. Значение формируется сложением четырех базовых контуров по строгому математическому правилу:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Управленческий баланс</span><div class="formula-heading">Расчет совокупной чистой стоимости активов мастера</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Абсолютный капитал</span><span class="math-op">=</span><span class="math-var">Ликвидные счета</span><span class="math-op">+</span><span class="math-var">Инвестиции</span><span class="math-op">+</span><span class="math-var">Личные активы</span><span class="math-op">+</span><span class="math-var">Чистые активы мастерских</span></div></div><div class="formula-card-bottom"><p>Активы рабочих пространств рассчитываются динамически: программа в реальном времени обращается к базам данных всех активных цехов, суммирует остатки касс, складские запасы материалов, себестоимость готовой продукции и амортизированную стоимость оборудования с учетом коэффициентов долей.</p></div></div><div class="info custom-block"><p class="custom-block-title">Мгновенная консолидация мультипространств</p><p>Если вы параллельно ведете столярный цех, студию индивидуального пошива и сервисный центр ремонта инструмента, сводка автоматически считывает локальные базы данных каждого направления. Вам не требуется вручную переключать рабочие пространства и складывать цифры на калькуляторе: консолидация происходит в фоне при открытии вкладки.</p></div><hr><h2 id="анализ-доходов-и-трат-четыре-индикатора-финансового-потока" tabindex="-1">Анализ доходов и трат: четыре индикатора финансового потока <a class="header-anchor" href="#анализ-доходов-и-трат-четыре-индикатора-финансового-потока" aria-label="Permalink to &quot;Анализ доходов и трат: четыре индикатора финансового потока&quot;">​</a></h2><p>Нижняя область экрана отведена под аналитическую панель доходов и расходов. Она сопоставляет результаты созидательной деятельности с реальным изменением благосостояния:</p><table class="craft-matrix-table"><thead><tr><th style="width:25%;">Заработано в бизнесах</th><th style="width:25%;">Внешние доходы / Накоплено</th><th style="width:25%;">Прибыль от инвестиций</th><th style="width:25%;">Свободные траты на жизнь</th></tr></thead><tbody><tr><td><strong>1 450 000,00 ₽</strong></td><td><strong>320 000,00 ₽</strong></td><td><strong style="color:#10b981;">+185 400,00 ₽</strong></td><td><strong>680 000,00 ₽</strong></td></tr></tbody></table><ol><li><strong>«Заработано в бизнесах»:</strong> совокупная операционная чистая прибыль всех мастерских за все время работы (валовая выручка за вычетом себестоимости списанных материалов, аренды, коммунальных услуг, расходников и амортизации оборудования);</li><li><strong>«Внешние доходы / Накоплено»:</strong> суммарный объем зафиксированных личных доходов из вкладки «Личные операции» (сторонние контрактные гонорары, преподавательская деятельность, продажа личных вещей);</li><li><strong>«Прибыль от инвестиций»:</strong> общий финансовый результат инвестиционного портфеля. Включает как нереализованную бумажную переоценку открытых позиций, так и чистую зафиксированную прибыль по закрытым сделкам. Отображается со знаком <code>+</code> изумрудного цвета при росте портфеля или <code>-</code> кирпично-красного цвета при просадке;</li><li><strong>«Свободные траты на жизнь»:</strong> объем личных потребительских расходов семьи мастера, вычисленный математическим путем без ручного сбора кассовых чеков.</li></ol><hr><h2 id="математика-свободных-бытовых-трат-по-балансовои-дельте" tabindex="-1">Математика свободных бытовых трат по балансовой дельте <a class="header-anchor" href="#математика-свободных-бытовых-трат-по-балансовои-дельте" aria-label="Permalink to &quot;Математика свободных бытовых трат по балансовой дельте&quot;">​</a></h2><p>Фундаментальное инженерное преимущество ОмниКрафт ЕРП — освобождение мастера от ведения домашней бухгалтерии. Система рассчитывает бытовые расходы семьи методом балансовой дельты чистых активов:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Балансовая дельта</span><div class="formula-heading">Автоматический расчет бытовых расходов семьи</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Траты на жизнь</span><span class="math-op">=</span><span class="math-var">Накопленный доходный пул</span><span class="math-op">−</span><span class="math-group">(</span><span class="math-var">Крупные личные расходы</span><span class="math-op">+</span><span class="math-var">Дельта капитала</span><span class="math-group">)</span></div></div><div class="formula-card-bottom"><p>Накопленный доходный пул = Прибыль всех мастерских + Внешние доходы + Доход от инвестиций. Если совокупный капитал вырос на меньшую сумму, чем суммарно заработано за период, недостающая разница признается естественными бытовыми тратами семьи на продукты, транспорт, быт и повседневные нужды.</p></div></div><p><strong>Пример практического расчета:</strong></p><ul><li>За отчетный период производственная мастерская принесла чистую прибыль <strong>300 000 ₽</strong>;</li><li>Внешние консультации дали личный доход <strong>50 000 ₽</strong>;</li><li>Инвестиционный портфель принес прибыль <strong>20 000 ₽</strong>;</li><li><em>Суммарный доходный пул составил 370 000 ₽</em>;</li><li>В журнале личных операций зафиксирован крупный целевой расход на лечение зубов — <strong>70 000 ₽</strong>;</li><li>Фактический капитал на всех счетах и в мастерских вырос на <strong>180 000 ₽</strong>.</li></ul><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Числовой пример</span><div class="formula-heading">Расчёт повседневных трат на жизнь</div></div><div class="formula-equation-box"><div class="math-line"><span class="math-var">Траты на жизнь</span><span class="math-op">=</span><span class="math-calc-expr">370 000 ₽ − (70 000 ₽ + 180 000 ₽) = <strong>120 000 ₽</strong></span></div></div><div class="formula-card-bottom"><p>Программа безошибочно определила: 120 000 ₽ ушли на повседневное жизнеобеспечение семьи без сбора чеков.</p></div></div><p>Программа безошибочно определила: 120 000 ₽ ушли на повседневное жизнеобеспечение семьи. Мастеру не потребовалось сохранять ни одного чека из супермаркета или автозаправочной станции.</p><hr><h2 id="преемственность-истории-снимки-закрытых-пространств" tabindex="-1">Преемственность истории: снимки закрытых пространств <a class="header-anchor" href="#преемственность-истории-снимки-закрытых-пространств" aria-label="Permalink to &quot;Преемственность истории: снимки закрытых пространств&quot;">​</a></h2><p>В реальной жизни мастерские могут менять юридическую форму, закрываться, объединяться или продаваться как готовый бизнес.</p><p>Если бы удаление старого рабочего пространства стирало связанные финансовые данные, исторический график капитала мастера обрушился бы, показав фиктивный провал благосостояния.</p><p>Для решения этой задачи в ОмниКрафт ЕРП реализован механизм <strong>несгораемых исторических снимков (слепки состояния)</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Удаление пространства] ➔ [Генерация финансового снимка] ➔ [Архив преемственности]</span></span></code></pre></div><ol><li><strong>Несгораемый слепок чистой прибыли:</strong> при удалении пространства программа фиксирует итоговый финансовый результат (заработанную прибыль и накопленный капитал на момент закрытия) в системной таблице снимков;</li><li><strong>Индикатор преемственности:</strong> под карточкой абсолютного капитала активируется информационная строка:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Иконка свитка] Срезов удаленных пространств: 2 | История капитала сохранена</span></span></code></pre></div></li><li><strong>Сохранение аналитических рядов:</strong> графики многолетней динамики благосостояния продолжают учитывать вклад закрытых направлений, гарантируя абсолютную достоверность финансовой биографии мастера.</li></ol><hr><h2 id="справочник-индикаторов-инфопанели" tabindex="-1">Справочник индикаторов инфопанели <a class="header-anchor" href="#справочник-индикаторов-инфопанели" aria-label="Permalink to &quot;Справочник индикаторов инфопанели&quot;">​</a></h2><p>В таблице приведены алгоритмы расчета и источники данных для каждого индикатора сводки:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Индикатор на экране</th><th style="text-align:left;">Источник данных в СУБД</th><th style="text-align:left;">Алгоритм агрегации</th><th style="text-align:left;">Экономический смысл</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>«Абсолютный капитал»</strong></td><td style="text-align:left;"><code>accounts</code>, <code>personal_assets</code>, БД пространств</td><td style="text-align:left;">Сумма ликвидности, портфеля, личного имущества и чистых активов цехов</td><td style="text-align:left;">Общая рыночная капитализация создателя</td></tr><tr><td style="text-align:left;"><strong>«Счета (Деньги)»</strong></td><td style="text-align:left;"><code>personal_accounts</code></td><td style="text-align:left;">Сумма балансов активных счетов с пересчетом по курсу валюты</td><td style="text-align:left;">Свободная наличность и банковские остатки</td></tr><tr><td style="text-align:left;"><strong>«Инвестиции»</strong></td><td style="text-align:left;"><code>personal_assets</code> (<code>asset_kind = &#39;investment&#39;</code>)</td><td style="text-align:left;">Текущая рыночная стоимость открытых инвестиционных инструментов</td><td style="text-align:left;">Резервы в ценных бумагах, крипте и займах</td></tr><tr><td style="text-align:left;"><strong>«Личные активы»</strong></td><td style="text-align:left;"><code>personal_assets</code> (<code>asset_kind = &#39;property&#39;</code>)</td><td style="text-align:left;">Оценочная стоимость объектов × персональная доля владения мастера</td><td style="text-align:left;">Недвижимость, земля и автомобили семьи</td></tr><tr><td style="text-align:left;"><strong>«Имущество пространств»</strong></td><td style="text-align:left;"><code>transactions</code>, <code>materials</code>, <code>products</code>, <code>assets</code> пространств</td><td style="text-align:left;">Остаток кассы + склад сырья МАК + склад готовой продукции ФИФО + станки за вычетом износа</td><td style="text-align:left;">Материально-производственная база бизнеса</td></tr><tr><td style="text-align:left;"><strong>«Заработано в бизнесах»</strong></td><td style="text-align:left;"><code>sales_log</code>, <code>transactions</code>, <code>assets</code> пространств</td><td style="text-align:left;">Выручка − себестоимость − накладные расходы − амортизация оборудования</td><td style="text-align:left;">Операционная чистая прибыль цехов</td></tr><tr><td style="text-align:left;"><strong>«Внешние доходы»</strong></td><td style="text-align:left;"><code>personal_transactions</code> (<code>type = &#39;income&#39;</code>)</td><td style="text-align:left;">Сумма всех зафиксированных внешних личных доходов</td><td style="text-align:left;">Заработки мастера за пределами мастерской</td></tr><tr><td style="text-align:left;"><strong>«Прибыль от инвестиций»</strong></td><td style="text-align:left;"><code>personal_assets</code></td><td style="text-align:left;">Нереализованный прирост открытых позиций + закрытый финансовый результат</td><td style="text-align:left;">Совокупная доходность инвестиций</td></tr><tr><td style="text-align:left;"><strong>«Свободные траты»</strong></td><td style="text-align:left;">Балансовая формула</td><td style="text-align:left;">Доходный пул − (Крупные траты + Дельта чистой стоимости)</td><td style="text-align:left;">Бытовой потребительский бюджет семьи</td></tr></tbody></table><hr><h2 id="панель-инструментов-и-режимы-работы" tabindex="-1">Панель инструментов и режимы работы <a class="header-anchor" href="#панель-инструментов-и-режимы-работы" aria-label="Permalink to &quot;Панель инструментов и режимы работы&quot;">​</a></h2><p>В верхней правой части инфопанели расположены сервисные элементы:</p><ul><li><strong>Кнопка «Обновить данные сводки»:</strong> принудительно пересканирует базы данных всех рабочих пространств и актуализирует валютные остатки без перезагрузки программы;</li><li><strong>Кнопка контекстной справки <code>[?]</code>:</strong> открывает настоящее руководство в браузере;</li><li><strong>Пустое состояние (Первый запуск):</strong> если в программе еще нет записей, экран отображает приветственную панель с предложением добавить первый счет либо активировать <strong>«Режим демонстрации»</strong> для изучения возможностей на учебных данных.</li></ul><div class="tip custom-block"><p class="custom-block-title">Совет мастера: как избежать иллюзии кассового разрыва</p><p>Никогда не оценивайте успешность мастерской исключительно по сумме денег на расчетной карте. Если за месяц касса уменьшилась на 200 000 ₽, но склад пополнился отборной кожей на 250 000 ₽, а цех выпустил партию изделий на 150 000 ₽, Ваш бизнес не понес убытков — его чистая стоимость выросла. Сводка капитала наглядно покажет этот рост в блоке «Имущество пространств».</p></div><div class="warning custom-block"><p class="custom-block-title">Защита от задвоения активов</p><p>Следите за корректным разделением долей владения во вкладке «Имущество и ресурсы». Если станок стоимостью 500 000 ₽ одновременно записан как 100% личный актив и 100% оборудование цеха, система посчитает его дважды, завысив Ваш капитал на полмиллиона рублей. Используйте инструмент проверки коллизий для поддержания чистоты баланса.</p></div>',51))])}const _=l(p,[["render",h]]);export{y as __pageData,_ as default};
